## Task
Add server action that verifies a magic-link token, creates session, and handles the new-user case (creates user + tenant + 15 credits matching existing signup behavior).

## Add to `src/app/pages/user/magicLink.ts`
```typescript
export const verifyMagicLink = serverAction(async (token: string): Promise<
  { success: true; isNewUser: boolean } | { success: false; error: 'expired' | 'used' | 'invalid' | 'server_error' }
> => {
  try {
    const { response } = requestInfo

    const result = await db.$transaction(async (tx) => {
      const authToken = await tx.authToken.findUnique({ where: { token } })
      if (!authToken) throw new Error('invalid')
      if (authToken.type !== 'MAGIC_LINK') throw new Error('invalid')
      if (authToken.used) throw new Error('used')
      if (new Date() > authToken.expiresAt) throw new Error('expired')

      // Mark used first (one-shot semantics even on failure below)
      await tx.authToken.update({ where: { id: authToken.id }, data: { used: true } })

      let userId = authToken.userId
      let tenantId: string | null = null
      let membershipId: string | null = null
      let isNewUser = false

      if (!userId) {
        // New user: create user + personal tenant + membership
        const freeCredits = parseInt(process.env.FREE_CREDITS_AMOUNT || '15', 10)
        const user = await tx.user.create({
          data: {
            email: authToken.email,
            username: authToken.email,
            creditsRemaining: freeCredits,
            totalCreditsGranted: freeCredits,
          },
        })
        const tenant = await tx.tenant.create({
          data: {
            name: `${authToken.email}'s Workspace`,
            slug: `${authToken.email.split('@')[0]}-${crypto.randomUUID().slice(0, 8)}`,
            status: 'ACTIVE',
          },
        })
        const membership = await tx.tenantMembership.create({
          data: { userId: user.id, tenantId: tenant.id, role: 'OWNER' },
        })
        userId = user.id
        tenantId = tenant.id
        membershipId = membership.id
        isNewUser = true
      } else {
        // Existing user: load primary tenant/membership
        const membership = await tx.tenantMembership.findFirst({
          where: { userId },
          orderBy: { createdAt: 'asc' },
        })
        tenantId = membership?.tenantId ?? null
        membershipId = membership?.id ?? null
      }

      return { userId, tenantId, membershipId, isNewUser }
    })

    // Session save happens outside transaction (need response.headers)
    await sessions.save(response.headers, {
      userId: result.userId,
      tenantId: result.tenantId,
      membershipId: result.membershipId,
    })

    return { success: true, isNewUser: result.isNewUser }
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'unknown'
    if (msg === 'expired' || msg === 'used' || msg === 'invalid') {
      return { success: false, error: msg }
    }
    console.error('verifyMagicLink failed:', msg)
    return { success: false, error: 'server_error' }
  }
})
```

