## Create `src/app/pages/user/authLookup.ts`
```typescript
'use server'
import { serverQuery } from 'rwsdk/worker'
import { db } from '@/db'
import { isRateLimited } from '@/app/interruptors/rateLimit'
import { requestInfo } from 'rwsdk/worker'

export type AuthLookupResult = {
  exists: boolean
  hasPassword: boolean
  hasPasskey: boolean
  rateLimited?: boolean
}

export const lookupAuthMethod = serverQuery(async (email: string): Promise<AuthLookupResult> => {
  const ip = requestInfo.request.headers.get('cf-connecting-ip') ?? 'unknown'
  if (isRateLimited(`auth-lookup:${ip}`, 20, 5 * 60 * 1000)) {
    return { exists: false, hasPassword: false, hasPasskey: false, rateLimited: true }
  }

  const normalized = email.trim().toLowerCase()
  const user = await db.user.findUnique({
    where: { email: normalized },
    select: {
      passwordHash: true,
      _count: { select: { credentials: true } },
    },
  })

  if (!user) return { exists: false, hasPassword: false, hasPasskey: false }
  return {
    exists: true,
    hasPassword: !!user.passwordHash,
    hasPasskey: user._count.credentials > 0,
  }
})
```

## Rate limit update (`src/app/interruptors/rateLimit.ts`)
Export `isRateLimited` and `CLEANUP_INTERVAL`-related helpers so it can be called inside server actions (not just as interruptors). Currently unexported.

## Test Steps
1. pnpm run types
2. Call with existing-user email → returns matching state
3. Call with non-existent email → `{exists:false,...}`
4. Call 21 times in 5 min from same IP → 21st returns `{rateLimited:true}`

## Enumeration stance
Returns `exists` explicitly — user has stated preference for identifier-first UX over enumeration hiding. Rate limit defends against bulk probing.

