## Task
Add server action `requestMagicLink(email)` that generates an `AuthToken` of type `MAGIC_LINK` and emails a sign-in link. Works for both existing users (userId set) and new-user signup (userId null, user created on verify).

## Create `src/app/pages/user/magicLink.ts` (new file — keep passwordReset.ts for its purpose)
```typescript
'use server'
import { serverAction, requestInfo } from 'rwsdk/worker'
import { db } from '@/db'
import { Resend } from 'resend'
import { env } from 'cloudflare:workers'
import { isRateLimited } from '@/app/interruptors/rateLimit'

type WorkerEnv = Env & { RESEND_API_KEY: string; APP_URL?: string }

function generateToken(): string {
  const array = new Uint8Array(32)
  crypto.getRandomValues(array)
  return Array.from(array, b => b.toString(16).padStart(2, '0')).join('')
}

export const requestMagicLink = serverAction(async (email: string): Promise<{ success: boolean; error?: string }> => {
  try {
    const workerEnv = env as WorkerEnv
    const normalized = email.trim().toLowerCase()

    // Rate limit per email + IP (5 per 15 min)
    const ip = requestInfo.request.headers.get('cf-connecting-ip') ?? 'unknown'
    if (isRateLimited(`magic:${ip}:${normalized}`, 5, 15 * 60 * 1000)) {
      return { success: false, error: 'Too many sign-in requests for this email. Wait 15 min.' }
    }

    if (!workerEnv.RESEND_API_KEY) {
      console.error('RESEND_API_KEY not configured')
      return { success: false, error: 'Email service not configured. Contact support.' }
    }

    // Check if user exists (for userId in token; null means pending signup)
    const user = await db.user.findUnique({ where: { email: normalized }, select: { id: true } })

    // Invalidate prior unused magic tokens for this email
    await db.authToken.deleteMany({
      where: { email: normalized, type: 'MAGIC_LINK', used: false },
    })

    const token = generateToken()
    const expiresAt = new Date(Date.now() + 15 * 60 * 1000) // 15 min

    await db.authToken.create({
      data: { email: normalized, userId: user?.id ?? null, type: 'MAGIC_LINK', token, expiresAt },
    })

    const magicUrl = `${workerEnv.APP_URL || 'https://routefast.app'}/user/magic?token=${token}`
    const resend = new Resend(workerEnv.RESEND_API_KEY)

    await resend.emails.send({
      from: 'RouteFast <noreply@digitalglue.dev>',
      to: email,
      replyTo: 'barrett@digitalglue.dev',
      subject: 'Sign in to RouteFast',
      html: `
        <h2>Sign in to RouteFast</h2>
        <p>Tap this button to sign in${user ? '' : ' — we\'ll set up your account automatically'}:</p>
        <p><a href="${magicUrl}" style="display:inline-block;padding:12px 24px;background:#d32f2f;color:#fff;text-decoration:none;border-radius:4px;font-weight:bold;">Sign in to RouteFast →</a></p>
        <p>Or copy this link: <br><a href="${magicUrl}">${magicUrl}</a></p>
        <p>This link expires in 15 minutes. If you didn't request it, ignore this email.</p>
        <p>— The RouteFast team</p>
      `,
    })

    return { success: true }
  } catch (err) {
    console.error('requestMagicLink failed:', err instanceof Error ? err.message : 'unknown')
    return { success: false, error: 'Failed to send sign-in email. Try again.' }
  }
})
```

